@startuml

class Game {
  + id : string
}

class Player {
  + id : string
}

class Deck {
  + id : string
}

class Card {
  + id : string
  + compareHeight(other: Card) : string
}

enum Suit {
  DIAMONDS
  HEARTS
  SPADES
  CLUBS
}

class ScoringTable {
  + id : string
}

class Round {
  + id : string
  + pointValue : int
  + isJackRound : boolean
  + isSoloRound : boolean
}

class JackRound extends Round {}

class SoloRound extends Round {}

class MandatorySoloRound extends SoloRound {}

class SoloType {
  TRUMP
  JACK
  QUEEN
}

class SoloPlayer {
  + id : string
}

Game "1" *-- "4" Player
Game "1" *-- "1" Deck
Game "1" *-- "1" ScoringTable
Deck "1" *-- "0..48" Card
ScoringTable "1" *-- "0..*" Round
Round "0..*" -- "1..*" Player : winning players
SoloRound "0..*" -- "1" SoloPlayer : solo player
Card "0..*" -- "1" Suit

@enduml

